fn extra_preview(title: &str, category: &str, desc: &str) -> String {
 format!(r#"{}<section class="section wrap"><div class="preview-notice"><span class="badge">معاينة فقط</span><h2>{}</h2><p>{}</p><p>هذه الصفحة للتعرّف على شكل المنصة، والوظيفة غير مفعّلة بعد. لا تُدخل بيانات شخصية أو مالية هنا.</p><div class="preview-links"><a class="btn btn-dark" href="/all-pages">تصفّح كل الصفحات ←</a><a class="arrow-link" href="/courses">اكتشف الكورسات</a></div></div></section>"#, hero_small(category,title,"صفحة ضمن التصوّر الأولي لمنصة Amigo."),title,desc)
}
fn all_pages() -> String {
 let groups: &[(&str,&[(&str,&str)])] = &[
 ("اكتشف Amigo", &[("/","الرئيسية"),("/faculties","الكليات"),("/courses","كتالوج الكورسات"),("/shared","الكورسات المشتركة"),("/pricing","الخطط والأسعار"),("/about","من نحن"),("/contact","اتصل بنا"),("/faq","الأسئلة الشائعة")]),
 ("حسابك ومساحتك", &[("/register","تسجيل حساب جديد"),("/login","تسجيل الدخول"),("/reset-password","استعادة كلمة المرور"),("/dashboard","لوحة الطالب"),("/student/profile","الملف الشخصي")]),
 ("المعلومات القانونية", &[("/terms","الشروط والأحكام"),("/privacy","سياسة الخصوصية"),("/refund","الاسترجاع والإلغاء")])];
 let mut out=String::new();
 for (name, links) in groups { out.push_str(&format!("<div class=\"group-heading\"><h2>{}</h2></div><div class=\"page-list\">{}</div>",name,links.iter().map(|(url,title)|format!("<a href=\"{}\"><span>{}</span><span>←</span></a>",url,title)).collect::<String>())); }
 for cat in ["الصفحات العامة", "الحساب", "الطالب", "المحاضر", "الإدارة", "المعلومات القانونية"] { let items=EXTRA_PAGES.iter().filter(|p|p.2==cat).map(|(url,title,_,_)|format!("<a href=\"{}\"><span>{}</span><small>معاينة</small><span>←</span></a>",url,title)).collect::<String>(); out.push_str(&format!("<div class=\"group-heading\"><h2>{}</h2></div><div class=\"page-list\">{}</div>",cat,items)); }
 format!("{}<section class=\"section wrap\"><p class=\"directory-note\">الصفحات المصنّفة «معاينة» توضّح التجربة المخططة، والخدمات المرتبطة بها غير مفعلة بعد.</p>{}</section>",hero_small("دليل المنصة","كل حاجة في مكان واحد.","تصفّح صفحات Amigo والوظائف المخططة للطلاب والمحاضرين والإدارة."),out)
}
const SITE_URL: &str = "https://amigo-gilt-nine.vercel.app";
const ROBOTS_TXT: &str = "User-agent: *\nAllow: /\nDisallow: /admin/\nDisallow: /dashboard/\nDisallow: /student/\nDisallow: /instructor/\nDisallow: /checkout/\nDisallow: /login/\nDisallow: /register/\nDisallow: /reset-password/\n\nSitemap: https://amigo-gilt-nine.vercel.app/sitemap.xml\n";
const SITEMAP_PATHS: &[&str] = &["/","/faculties","/courses","/shared","/pricing","/about","/blog","/contact","/faq","/all-pages","/terms","/privacy","/refund","/copyright"];
fn sitemap_xml() -> String { let mut out=String::from("<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<urlset xmlns=\"http://www.sitemaps.org/schemas/sitemap/0.9\">\n"); for p in SITEMAP_PATHS { let loc=if *p=="/" { format!("{}/",SITE_URL) } else { format!("{}{}/",SITE_URL,p) }; out.push_str(&format!("<url><loc>{}</loc></url>\n",loc)); } out.push_str("</urlset>\n"); out }
fn export_static(root: &str) -> std::io::Result<()> {
 use std::path::Path;
 let base=Path::new(root); std::fs::create_dir_all(base.join("static"))?;
 std::fs::write(base.join("static/hero-student.png"),include_bytes!("../static/hero-student.png"))?;
 std::fs::write(base.join("static/demo-course-digital.png"),include_bytes!("../static/demo-course-digital.png"))?;
 std::fs::write(base.join("static/demo-course-math.png"),include_bytes!("../static/demo-course-math.png"))?;
 std::fs::write(base.join("static/demo-instructor-sara.png"),include_bytes!("../static/demo-instructor-sara.png"))?;
 std::fs::write(base.join("static/demo-instructor-karim.png"),include_bytes!("../static/demo-instructor-karim.png"))?;
 std::fs::write(base.join("static/course-accounting.png"),include_bytes!("../static/course-accounting.png"))?;
 std::fs::write(base.join("static/course-computer.png"),include_bytes!("../static/course-computer.png"))?;
 std::fs::write(base.join("static/course-data.png"),include_bytes!("../static/course-data.png"))?;
 std::fs::write(base.join("static/instructor-sara.jpg"),include_bytes!("../static/instructor-sara.jpg"))?;
 std::fs::write(base.join("static/instructor-karim.jpg"),include_bytes!("../static/instructor-karim.jpg"))?;
 std::fs::write(base.join("static/instructor-mona.jpg"),include_bytes!("../static/instructor-mona.jpg"))?;
 std::fs::write(base.join("static/course-intro-pt.png"),include_bytes!("../static/course-intro-pt.png"))?;
 std::fs::write(base.join("static/course-anatomy.png"),include_bytes!("../static/course-anatomy.png"))?;
 std::fs::write(base.join("static/instructor-khaled.jpg"),include_bytes!("../static/instructor-khaled.jpg"))?;
 std::fs::write(base.join("static/style.css"),include_str!("../static/style.css"))?;
 std::fs::write(base.join("static/app.js"),include_str!("../static/app.js"))?;
 std::fs::write(base.join("static/firebase-auth.js"),include_str!("../static/firebase-auth.js"))?;
 std::fs::write(base.join("static/firebase-core.js"),include_str!("../static/firebase-core.js"))?;
 std::fs::write(base.join("static/catalog.js"),include_str!("../static/catalog.js"))?;
 std::fs::write(base.join("static/admin-dashboard.js"),include_str!("../static/admin-dashboard.js"))?;
 std::fs::write(base.join("static/i18n.js"),include_str!("../static/i18n.js"))?;
 std::fs::write(base.join("static/i18n-dict.js"),include_str!("../static/i18n-dict.js"))?;
 std::fs::write(base.join("static/favicon.svg"),include_str!("../static/favicon.svg"))?;
 std::fs::write(base.join("robots.txt"),ROBOTS_TXT)?;
 std::fs::write(base.join("sitemap.xml"),sitemap_xml())?;
 let (_,not_found_html)=page("/page-not-found"); std::fs::write(base.join("404.html"),not_found_html)?;
 let mut paths: Vec<String> = ["/","/all-pages","/faculties","/faculty","/courses","/course","/shared","/pricing","/register","/login","/dashboard","/reset-password","/student/profile","/instructors","/about","/contact","/faq","/terms","/privacy","/refund"].iter().map(|p|p.to_string()).collect();
 paths.extend(EXTRA_PAGES.iter().map(|p|p.0.to_string()));
 for path in paths { let (status, html)=page(&path); assert_eq!(status,200,"missing page: {}",path); let dir=base.join(path.trim_start_matches('/')); std::fs::create_dir_all(&dir)?; std::fs::write(dir.join("index.html"),html)?; }
 Ok(())
}
fn page(path:&str)->(u16,String) { let (status,title,body) = match path {
 "/"=>(200,"الرئيسية",home()),
 "/all-pages"=>(200,"كل الصفحات",all_pages()),
 "/faculties"=>(200,"الكليات",format!("{}<section class=\"section wrap\"><div id=\"faculty-list\" class=\"faculty-grid\" role=\"status\">جاري تحميل الكليات…</div></section>",hero_small("كليتك هنا","لكل كلية حكاية.","اختر كليتك واكتشف الكورسات المرتبطة بها."))),
 "/faculty"=>(200,"الكلية",faculty_page()), "/course"=>(200,"الكورس",course_page()),
 "/courses"=>(200,"الكورسات",catalog(false)), "/shared"=>(200,"الكورسات المشتركة",catalog(true)),
 "/pricing"=>(200,"الخطط",pricing()), "/register"=>(200,"ابدأ",auth(true)), "/login"=>(200,"الدخول",auth(false)), "/dashboard"=>(200,"مساحتك",dashboard()), "/reset-password"=>(200,"استعادة كلمة المرور",reset_password()), "/student/profile"=>(200,"الملف الشخصي",profile()),
 "/instructors"=>(200,"المحاضرون",r#"<script>location.replace('/courses')</script><section class="section wrap"><h2>المحاضرون</h2><p>ستجد المحاضرين وصورهم أسفل كل كورس. You will find the instructors with their photos under each course.</p><p><a class="button primary" href="/courses">تصفح الكورسات</a></p></section>"#.to_owned()),
 "/about"=>(200,"من نحن",info("نتعلّم ونكبر معًا.","<h2>صاحبك في رحلة التعلّم.</h2><p>Amigo مساحة تعليمية تهدف إلى تقريب المعرفة للطلاب وتنظيم الكورسات حسب الكلية والاهتمامات المشتركة.</p><p>لا تشير هذه النسخة التجريبية إلى اعتماد أو شراكة رسمية مع أي جامعة أو كلية.</p>")),
 "/contact"=>(200,"تواصل معنا",info("خلّينا على تواصل.","<h2>نحب نسمع منك.</h2><p>سيتم إضافة البريد ووسائل التواصل الرسمية عند إطلاق المنصة.</p>")),
 "/faq"=>(200,"الأسئلة الشائعة",info("أسئلة ممكن تكون عندك.","<h2>هل يمكنني التسجيل أو الدفع الآن؟</h2><p>الحسابات متاحة للتجربة؛ الدفع ومحتوى الكورسات الفعلي غير مفعّلين بعد.</p><h2>ما هو الكورس المشترك؟</h2><p>كورس واحد مرتبط بأكثر من كلية. قد يكون مشتركًا بين بعض الكليات أو جميعها.</p>")),
 "/terms"=>(200,"الشروط والأحكام",info("الشروط والأحكام", "<p>ستُنشر الشروط المعتمدة قبل إطلاق الخدمة والتسجيل الفعلي.</p>")), "/privacy"=>(200,"الخصوصية",info("سياسة الخصوصية", "<p>تُستخدم بيانات الحساب والكلية والفرقة لتقديم التوصيات وتُحفظ لدى Firebase. ستُنشر سياسة الخصوصية المعتمدة قبل الإطلاق العام.</p>")), "/refund"=>(200,"الاسترجاع والإلغاء",info("الاسترجاع والإلغاء", "<p>ستُنشر سياسة الاسترجاع والإلغاء المعتمدة قبل تفعيل الدفع.</p>")),
 p if EXTRA_PAGES.iter().any(|item| item.0 == p) => { let (_,title,category,desc)=EXTRA_PAGES.iter().find(|item|item.0==p).unwrap(); (200,*title,extra_preview(title,category,desc)) },

 _=>(404,"غير موجود",info("الصفحة غير موجودة", "<p>جرّب الرجوع للرئيسية.</p>")) }; (status,layout(title,&body)) }
fn respond(mut stream: TcpStream) -> std::io::Result<()> { stream.set_read_timeout(Some(std::time::Duration::from_secs(5)))?; let mut buffer=[0;8192]; let n=stream.read(&mut buffer)?; let request=String::from_utf8_lossy(&buffer[..n]); let mut parts=request.lines().next().unwrap_or("").split_whitespace(); let method=parts.next().unwrap_or(""); let target=parts.next().unwrap_or("/"); let path=target.split('?').next().unwrap_or("/"); let image: Option<(&[u8],&str)>=match path { "/static/hero-student.png"=>Some((include_bytes!("../static/hero-student.png"),"image/png")), "/static/demo-course-digital.png"=>Some((include_bytes!("../static/demo-course-digital.png"),"image/png")), "/static/demo-course-math.png"=>Some((include_bytes!("../static/demo-course-math.png"),"image/png")), "/static/demo-instructor-sara.png"=>Some((include_bytes!("../static/demo-instructor-sara.png"),"image/png")), "/static/demo-instructor-karim.png"=>Some((include_bytes!("../static/demo-instructor-karim.png"),"image/png")), "/static/course-accounting.png"=>Some((include_bytes!("../static/course-accounting.png"),"image/png")), "/static/course-computer.png"=>Some((include_bytes!("../static/course-computer.png"),"image/png")), "/static/course-data.png"=>Some((include_bytes!("../static/course-data.png"),"image/png")), "/static/instructor-sara.jpg"=>Some((include_bytes!("../static/instructor-sara.jpg"),"image/jpeg")), "/static/instructor-karim.jpg"=>Some((include_bytes!("../static/instructor-karim.jpg"),"image/jpeg")), "/static/instructor-mona.jpg"=>Some((include_bytes!("../static/instructor-mona.jpg"),"image/jpeg")), "/static/course-intro-pt.png"=>Some((include_bytes!("../static/course-intro-pt.png"),"image/png")), "/static/course-anatomy.png"=>Some((include_bytes!("../static/course-anatomy.png"),"image/png")), "/static/instructor-khaled.jpg"=>Some((include_bytes!("../static/instructor-khaled.jpg"),"image/jpeg")), _=>None }; if let Some(img)=image.filter(|_| method=="GET" || method=="HEAD") { write!(stream,"HTTP/1.1 200 OK\r\nContent-Type: {}\r\nContent-Length: {}\r\nX-Content-Type-Options: nosniff\r\nConnection: close\r\n\r\n",img.1,img.0.len())?; if method=="GET" {stream.write_all(img.0)?;} return Ok(()); } let (status,mime,body)=if method!="GET" && method!="HEAD" {(405,"text/plain; charset=utf-8","Method not allowed".to_owned())} else {match path {"/static/style.css"=>(200,"text/css; charset=utf-8",include_str!("../static/style.css").to_owned()),"/static/app.js"=>(200,"text/javascript; charset=utf-8",include_str!("../static/app.js").to_owned()),"/static/firebase-auth.js"=>(200,"text/javascript; charset=utf-8",include_str!("../static/firebase-auth.js").to_owned()),"/static/firebase-core.js"=>(200,"text/javascript; charset=utf-8",include_str!("../static/firebase-core.js").to_owned()),"/static/catalog.js"=>(200,"text/javascript; charset=utf-8",include_str!("../static/catalog.js").to_owned()),"/static/admin-dashboard.js"=>(200,"text/javascript; charset=utf-8",include_str!("../static/admin-dashboard.js").to_owned()),"/static/i18n.js"=>(200,"text/javascript; charset=utf-8",include_str!("../static/i18n.js").to_owned()),"/static/i18n-dict.js"=>(200,"text/javascript; charset=utf-8",include_str!("../static/i18n-dict.js").to_owned()),"/static/favicon.svg"=>(200,"image/svg+xml; charset=utf-8",include_str!("../static/favicon.svg").to_owned()),"/robots.txt"=>(200,"text/plain; charset=utf-8",ROBOTS_TXT.to_owned()),"/sitemap.xml"=>(200,"application/xml; charset=utf-8",sitemap_xml()),_=>{let(s,b)=page(path);(s,"text/html; charset=utf-8",b)}}}; let reason=match status {200=>"OK",404=>"Not Found",_=>"Method Not Allowed"}; write!(stream,"HTTP/1.1 {} {}\r\nContent-Type: {}\r\nContent-Length: {}\r\nX-Content-Type-Options: nosniff\r\nConnection: close\r\n\r\n",status,reason,mime,body.len())?; if method!="HEAD" {stream.write_all(body.as_bytes())?;} Ok(()) }
fn main()->std::io::Result<()> { let args: Vec<String> = std::env::args().collect(); if args.get(1).map(String::as_str)==Some("--export") { return export_static(args.get(2).map(String::as_str).unwrap_or("dist")); } let address=std::env::var("AMIGO_BIND").unwrap_or_else(|_|"127.0.0.1:3000".into()); let listener=TcpListener::bind(&address)?; eprintln!("Amigo listening on http://{}",address); for connection in listener.incoming() { match connection {Ok(stream)=>{thread::spawn(move||{if let Err(e)=respond(stream){eprintln!("request error: {e}");}});},Err(e)=>eprintln!("connection error: {e}")}} Ok(()) }
